import{_ as l,o as i,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"VPS 监控功能说明","description":"","frontmatter":{"title":"VPS 监控功能说明"},"headers":[],"relativePath":"ops-knowledge-base/vps/monitoring-guide.md","filePath":"ops-knowledge-base/vps/monitoring-guide.md","lastUpdated":1788259091000}'),o={name:"ops-knowledge-base/vps/monitoring-guide.md"};function t(p,a,h,n,u,s){return i(),e("div",null,[...a[0]||(a[0]=[r('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍 VPS 控制台中的监控及用量统计功能，帮助客户查看服务器运行状态、资源使用情况及网络流量统计，便于日常运维和性能分析。</p><p><strong>适用产品：</strong></p><ul><li>VPS</li></ul><hr><h2 id="一、进入监控页面" tabindex="-1">一、进入监控页面 <a class="header-anchor" href="#一、进入监控页面" aria-label="Permalink to &quot;一、进入监控页面&quot;">​</a></h2><p>操作步骤：</p><ol><li>登录 Raksmart 客户后台。</li><li>进入 <strong>产品管理 → VPS</strong>。</li><li>选择需要管理的 VPS。</li><li>进入 VPS 管理页面。</li><li>默认进入 <strong>图表（监控）</strong> 页面。</li></ol><p>页面上方可切换：</p><ul><li>图表</li><li>用量</li></ul><hr><h2 id="二、图表-实时监控" tabindex="-1">二、图表（实时监控） <a class="header-anchor" href="#二、图表-实时监控" aria-label="Permalink to &quot;二、图表（实时监控）&quot;">​</a></h2><p>&quot;图表&quot;页面用于查看 VPS 当前资源运行状态，可实时了解服务器各项资源使用情况。</p><p>目前支持以下监控项目：</p><ul><li>CPU 使用率</li><li>硬盘 IO</li><li>内存使用量</li><li>网卡流量</li></ul><p>客户可通过监控图表观察服务器运行情况，例如：</p><ul><li>CPU 是否持续占用过高；</li><li>是否存在异常磁盘读写；</li><li>内存是否不足；</li><li>网络流量是否异常。</li></ul><p>说明：</p><p>监控数据会持续更新，可用于日常性能监控及故障排查。</p><hr><h2 id="cpu-使用率" tabindex="-1">CPU 使用率 <a class="header-anchor" href="#cpu-使用率" aria-label="Permalink to &quot;CPU 使用率&quot;">​</a></h2><p>用于查看服务器 CPU 使用情况。</p><p>适用于：</p><ul><li>查看 CPU 是否长期处于高负载；</li><li>判断是否存在程序占用 CPU；</li><li>分析业务高峰期间 CPU 使用变化。</li></ul><hr><h2 id="硬盘-io" tabindex="-1">硬盘 IO <a class="header-anchor" href="#硬盘-io" aria-label="Permalink to &quot;硬盘 IO&quot;">​</a></h2><p>用于查看磁盘读写情况。</p><p>支持选择不同磁盘进行查看（如系统盘或数据盘）。</p><p>适用于：</p><ul><li>分析磁盘读写压力；</li><li>判断是否存在大量磁盘 IO；</li><li>排查因磁盘性能导致的系统卡顿。</li></ul><hr><h2 id="内存使用量" tabindex="-1">内存使用量 <a class="header-anchor" href="#内存使用量" aria-label="Permalink to &quot;内存使用量&quot;">​</a></h2><p>用于查看服务器内存使用情况。</p><p>适用于：</p><ul><li>查看当前内存占用；</li><li>判断是否存在内存不足；</li><li>分析业务运行期间内存变化趋势。</li></ul><hr><h2 id="网卡流量" tabindex="-1">网卡流量 <a class="header-anchor" href="#网卡流量" aria-label="Permalink to &quot;网卡流量&quot;">​</a></h2><p>用于查看服务器网络流量情况。</p><p>支持查看网卡实时收发流量。</p><p>适用于：</p><ul><li>查看当前网络使用情况；</li><li>分析业务访问流量；</li><li>排查异常网络流量。</li></ul><hr><h2 id="三、用量统计" tabindex="-1">三、用量统计 <a class="header-anchor" href="#三、用量统计" aria-label="Permalink to &quot;三、用量统计&quot;">​</a></h2><p>&quot;用量&quot;页面用于统计 VPS 的网络流量使用情况。</p><p>页面支持：</p><ul><li>查看历史流量统计；</li><li>按时间范围查询；</li><li>自定义开始及结束时间。</li></ul><p>客户可根据需要查看指定时间段内的流量使用情况，便于统计业务流量及分析网络使用趋势。</p><p>说明：</p><p>用量统计主要用于查看网络流量，不同时间范围的数据可能存在一定的统计延迟。</p><hr><h2 id="四、常见问题" tabindex="-1">四、常见问题 <a class="header-anchor" href="#四、常见问题" aria-label="Permalink to &quot;四、常见问题&quot;">​</a></h2><h3 id="q1-为什么监控图表没有数据显示" tabindex="-1">Q1：为什么监控图表没有数据显示？ <a class="header-anchor" href="#q1-为什么监控图表没有数据显示" aria-label="Permalink to &quot;Q1：为什么监控图表没有数据显示？&quot;">​</a></h3><p>请确认以下内容：</p><ul><li>VPS 是否正常运行；</li><li>是否等待监控数据完成采集；</li><li>是否选择了正确的监控项目。</li></ul><p>如果服务器刚创建或刚开机，监控数据可能需要等待一段时间后才会显示。</p><hr><h3 id="q2-cpu-一直很高怎么办" tabindex="-1">Q2：CPU 一直很高怎么办？ <a class="header-anchor" href="#q2-cpu-一直很高怎么办" aria-label="Permalink to &quot;Q2：CPU 一直很高怎么办？&quot;">​</a></h3><p>建议先登录服务器检查：</p><ul><li>是否有业务程序占用 CPU；</li><li>是否存在异常进程；</li><li>是否有计划任务持续运行。</li></ul><p>如确认属于业务负载较高，可根据实际需求升级 VPS 配置。</p><hr><h3 id="q3-为什么内存使用率很高" tabindex="-1">Q3：为什么内存使用率很高？ <a class="header-anchor" href="#q3-为什么内存使用率很高" aria-label="Permalink to &quot;Q3：为什么内存使用率很高？&quot;">​</a></h3><p>内存占用较高不一定属于异常。</p><p>Linux 系统通常会使用部分空闲内存作为缓存（Cache），建议结合实际可用内存及业务运行情况综合判断。</p><hr><h3 id="q4-为什么硬盘-io-持续较高" tabindex="-1">Q4：为什么硬盘 IO 持续较高？ <a class="header-anchor" href="#q4-为什么硬盘-io-持续较高" aria-label="Permalink to &quot;Q4：为什么硬盘 IO 持续较高？&quot;">​</a></h3><p>可能原因包括：</p><ul><li>数据库频繁读写；</li><li>文件大量读写；</li><li>程序持续进行磁盘操作。</li></ul><p>建议登录服务器进一步分析具体原因。</p><hr><h3 id="q5-可以查看历史流量吗" tabindex="-1">Q5：可以查看历史流量吗？ <a class="header-anchor" href="#q5-可以查看历史流量吗" aria-label="Permalink to &quot;Q5：可以查看历史流量吗？&quot;">​</a></h3><p>可以。</p><p>在 <strong>用量</strong> 页面中，可选择指定日期范围，查看对应时间段内的网络流量统计。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 监控数据仅用于反映服务器资源使用情况，不代表服务器性能一定存在异常。</p><p>⚠️ 若服务器刚创建、刚重启或刚恢复运行，监控数据可能需要等待一段时间后才会更新。</p><p>⚠️ 用量统计支持按日期范围查询，建议根据业务需要选择对应的时间段进行查看。</p><p>⚠️ 如发现 CPU、内存、硬盘 IO 或网络流量持续异常，建议先登录服务器检查业务运行情况，再根据实际需求进行资源优化或升级。</p><hr>',80)])])}const q=l(o,[["render",t]]);export{c as __pageData,q as default};
